						const w = entryWeight(e);
						if (w !== 1) parts.push(String(w));
						const when = entryWhen(e);
						if (when !== null) parts.push(whenSpecOf(when));
						const rarity = entryRarity(e);
						if (rarity !== null) parts.push("rarity:" + rarity);
