					officialRecommendedSpeed: DEFAULT_CONFIG.whaleTailMotion.officialRecommendedSpeed,
					tpsMaxSpeed: String(whaleTailTpsMaxSpeed(DEFAULT_CONFIG.whaleTailMotion)),
					toolSwitchEnabled: DEFAULT_CONFIG.whaleTailMotion.toolSwitchEnabled,
					toolSwitchChance: String(DEFAULT_CONFIG.whaleTailMotion.toolSwitchChance * 100),
